<?php
require_once __DIR__.'/includes/auth.php'; require_role(['administrador','ventanilla','enrutador','calidad']);
$pdo=db(); $q=trim($_GET['q']??''); $params=[]; $sql='SELECT s.*,p.nombre AS punto,u.nombres AS operador FROM solicitudes s JOIN puntos_atencion p ON p.id_punto=s.id_punto JOIN usuarios u ON u.id_usuario=s.id_usuario';
if($q!==''){ $sql.=' WHERE s.nombres LIKE ? OR s.apellidos LIKE ? OR s.barrio LIKE ? OR s.celular LIKE ? OR s.direccion LIKE ?'; $like='%'.$q.'%'; $params=[$like,$like,$like,$like,$like]; }
$sql.=' ORDER BY s.fecha_registro DESC LIMIT 300'; $st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
$pageTitle='Solicitudes';require __DIR__.'/includes/header.php';
?>
<div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><div class="eyebrow">GESTIÓN DE REGISTROS</div><h1 class="page-title">Solicitudes</h1><p class="text-secondary mb-0">Consulta de las solicitudes almacenadas.</p></div><?php if(has_role(['administrador','ventanilla'])): ?><a class="btn btn-primary" href="nueva_solicitud.php">+ Nueva solicitud</a><?php endif; ?></div>
<div class="content-card"><form class="row g-2 mb-3"><div class="col-md-6"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Buscar por nombre, barrio, celular o dirección"></div><div class="col-auto"><button class="btn btn-outline-primary">Buscar</button></div><div class="col-auto"><a href="solicitudes.php" class="btn btn-light">Limpiar</a></div></form><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Código</th><th>Solicitante</th><th>Contacto</th><th>Ubicación</th><th>Punto</th><th>Fecha</th><th>Mapa</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td>#<?= (int)$r['id_solicitud'] ?></td><td class="fw-semibold"><?= e($r['nombres'].' '.$r['apellidos']) ?></td><td><?= e($r['celular']) ?></td><td><?= e($r['direccion'].' · '.$r['barrio'].' · '.$r['comuna']) ?></td><td><?= e($r['punto']) ?></td><td><?= e(date('d/m/Y H:i',strtotime($r['fecha_registro']))) ?></td><td><a target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=<?= e((string)$r['latitud']) ?>&mlon=<?= e((string)$r['longitud']) ?>#map=17/<?= e((string)$r['latitud']) ?>/<?= e((string)$r['longitud']) ?>">Ver ubicación</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="text-center text-secondary py-4">No se encontraron solicitudes.</td></tr><?php endif; ?></tbody></table></div><div class="small text-secondary">Se muestran máximo 300 registros por consulta.</div></div>
